META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–7: ಶ್ರೀಕೃಷ್ಣ ದೇವತೆಗಳು, ಋಷಿಗಳು ಮತ್ತು ಜೀವಿಗಳ ಪ್ರತಿಯೊಂದು ಗುಣದ ಜನ್ಮರಹಿತ ಮೂಲ; 8–11: ಜ್ಞಾನಿಗಳು ಅವನನ್ನು ಹೇಗೆ ಭಜಿಸುತ್ತಾರೆ, ಅವನು ಅವರಿಗೆ ಏನು ಕೊಡುತ್ತಾನೆ; 12–18: ಅರ್ಜುನ ಇದನ್ನು ಒಪ್ಪಿ ಅವನ ವಿಭೂತಿಗಳನ್ನು ಕೇಳಲು ಬಯಸುತ್ತಾನೆ; 19–38: "ಇವುಗಳಲ್ಲಿ ನಾನು ಇದು": ಪ್ರತಿಯೊಂದು ವರ್ಗದ ಶ್ರೇಷ್ಠ; 39–42: ಅವನಿಲ್ಲದೆ ಏನೂ ಇಲ್ಲ, ಇದೆಲ್ಲವೂ ಅವನ ಒಂದು ಸಣ್ಣ ಅಂಶ ಮಾತ್ರ.',
)
T = {
1: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಹೇ ಮಹಾಬಾಹು, ನನ್ನ ಪರಮ ವಚನವನ್ನು ಮತ್ತೆ ಕೇಳು. ಇದನ್ನು ಕೇಳಿ ನೀನು ಆನಂದಿಸುತ್ತೀಯ, ನಾನು ನಿನ್ನ ಹಿತವನ್ನು ಬಯಸುತ್ತೇನೆ, ಆದ್ದರಿಂದ ನಿನಗೆ ಹೇಳುತ್ತೇನೆ.',
2: 'ನನ್ನ ಉತ್ಪತ್ತಿಯನ್ನು ದೇವತೆಗಳೂ ತಿಳಿಯರು, ಮಹರ್ಷಿಗಳೂ ತಿಳಿಯರು, ಏಕೆಂದರೆ ಎಲ್ಲ ರೀತಿಯಲ್ಲೂ ದೇವತೆಗಳಿಗೂ ಮಹರ್ಷಿಗಳಿಗೂ ಮೂಲ ನಾನೇ.',
3: 'ನನ್ನನ್ನು ಜನ್ಮರಹಿತ, ಅನಾದಿ ಮತ್ತು ಲೋಕಗಳ ಮಹೇಶ್ವರ ಎಂದು ತಿಳಿದವನು ಮನುಷ್ಯರಲ್ಲಿ ಮೋಹರಹಿತನಾಗಿ ಎಲ್ಲ ಪಾಪಗಳಿಂದ ಮುಕ್ತನಾಗುತ್ತಾನೆ.',
4: 'ಬುದ್ಧಿ, ಜ್ಞಾನ, ಮೋಹವಿಲ್ಲದಿರುವಿಕೆ, ಕ್ಷಮೆ, ಸತ್ಯ, ಇಂದ್ರಿಯನಿಗ್ರಹ, ಮನಶ್ಶಾಂತಿ, ಸುಖ, ದುಃಖ, ಹುಟ್ಟು, ಸಾವು, ಭಯ ಮತ್ತು ಅಭಯ,',
5: 'ಅಹಿಂಸೆ, ಸಮತೆ, ಸಂತೋಷ, ತಪಸ್ಸು, ದಾನ, ಕೀರ್ತಿ ಮತ್ತು ಅಪಕೀರ್ತಿ: ಜೀವಿಗಳ ಈ ಬೇರೆ ಬೇರೆ ಭಾವಗಳು ನನ್ನಿಂದಲೇ ಹುಟ್ಟುತ್ತವೆ.',
6: 'ಸಪ್ತರ್ಷಿಗಳು, ಅವರಿಗಿಂತ ಹಿಂದಿನ ನಾಲ್ವರು (ಸನಕಾದಿಗಳು) ಮತ್ತು ಮನುಗಳು ನನ್ನ ಭಾವದಿಂದ ಕೂಡಿದವರು, ನನ್ನ ಮನಸ್ಸಿನಿಂದ ಹುಟ್ಟಿದವರು. ಲೋಕದ ಈ ಎಲ್ಲ ಪ್ರಜೆಗಳು ಅವರಿಂದಲೇ ಬಂದವರು.',
7: 'ನನ್ನ ಈ ವಿಭೂತಿಯನ್ನೂ ಯೋಗಶಕ್ತಿಯನ್ನೂ ತತ್ತ್ವವಾಗಿ ತಿಳಿದವನು ಅಚಲ ಯೋಗದಿಂದ ನನ್ನೊಂದಿಗೆ ಕೂಡುತ್ತಾನೆ, ಇದರಲ್ಲಿ ಸಂಶಯವಿಲ್ಲ.',
8: 'ಎಲ್ಲದರ ಉತ್ಪತ್ತಿಗೆ ಕಾರಣ ನಾನೇ, ನನ್ನಿಂದಲೇ ಎಲ್ಲವೂ ನಡೆಯುತ್ತದೆ. ಇದನ್ನು ತಿಳಿದು ಜ್ಞಾನಿಗಳು ಪೂರ್ಣ ಭಾವದಿಂದ ನನ್ನನ್ನು ಭಜಿಸುತ್ತಾರೆ.',
9: 'ಅವರ ಮನಸ್ಸು ನನ್ನಲ್ಲಿರುತ್ತದೆ, ಅವರ ಪ್ರಾಣ ನನಗೆ ಅರ್ಪಿತವಾಗಿರುತ್ತದೆ. ಪರಸ್ಪರ ನನ್ನ ಬಗ್ಗೆ ತಿಳಿಸಿಕೊಡುತ್ತಾ, ಸದಾ ನನ್ನ ಬಗ್ಗೆಯೇ ಮಾತನಾಡುತ್ತಾ ಅವರು ತೃಪ್ತರಾಗಿ ಆನಂದದಿಂದ ಇರುತ್ತಾರೆ.',
10: 'ಸದಾ ನನ್ನೊಂದಿಗೆ ಕೂಡಿ, ಪ್ರೀತಿಯಿಂದ ನನ್ನನ್ನು ಭಜಿಸುವವರಿಗೆ, ಅವರು ನನ್ನನ್ನು ಸೇರುವ ಬುದ್ಧಿಯೋಗವನ್ನು ನಾನು ಕೊಡುತ್ತೇನೆ.',
11: 'ಅವರ ಮೇಲಿನ ಕರುಣೆಯಿಂದಲೇ, ಅವರ ಹೃದಯದಲ್ಲಿದ್ದು, ಅಜ್ಞಾನದಿಂದ ಹುಟ್ಟಿದ ಕತ್ತಲೆಯನ್ನು ಹೊಳೆಯುವ ಜ್ಞಾನದೀಪದಿಂದ ನಾಶಮಾಡುತ್ತೇನೆ.',
12: 'ಅರ್ಜುನ ಹೇಳಿದನು: ನೀವು ಪರಬ್ರಹ್ಮ, ಪರಮ ಧಾಮ, ಪರಮ ಪವಿತ್ರ. ನೀವು ಸನಾತನ ದಿವ್ಯ ಪುರುಷ, ದೇವತೆಗಳಿಗೂ ಆದಿ, ಜನ್ಮರಹಿತ, ಸರ್ವವ್ಯಾಪಿ.',
13: 'ಎಲ್ಲ ಋಷಿಗಳೂ ನಿಮ್ಮನ್ನು ಹೀಗೆಯೇ ಹೇಳುತ್ತಾರೆ: ದೇವರ್ಷಿ ನಾರದ, ಅಸಿತ, ದೇವಲ ಮತ್ತು ವ್ಯಾಸರೂ. ಈಗ ನೀವೇ ನನಗೆ ಅದನ್ನು ಹೇಳುತ್ತಿದ್ದೀರಿ.',
14: 'ಹೇ ಕೇಶವ, ನೀವು ನನಗೆ ಹೇಳುವುದೆಲ್ಲವನ್ನೂ ಸತ್ಯವೆಂದು ನಂಬುತ್ತೇನೆ. ಹೇ ಭಗವನ್, ನಿಮ್ಮ ನಿಜವಾದ ಸ್ವರೂಪವನ್ನು ದೇವತೆಗಳೂ ತಿಳಿಯರು, ದಾನವರೂ ತಿಳಿಯರು.',
15: 'ಹೇ ಪುರುಷೋತ್ತಮ, ಜೀವಿಗಳ ಸೃಷ್ಟಿಕರ್ತ, ಜೀವಿಗಳ ಈಶ್ವರ, ದೇವದೇವ, ಜಗತ್ಪತಿ, ನಿಮ್ಮನ್ನು ನೀವೇ ನಿಮ್ಮಿಂದ ತಿಳಿಯುತ್ತೀರಿ.',
16: 'ಯಾವ ವಿಭೂತಿಗಳಿಂದ ನೀವು ಈ ಎಲ್ಲ ಲೋಕಗಳನ್ನೂ ವ್ಯಾಪಿಸಿದ್ದೀರೋ, ನಿಮ್ಮ ಆ ದಿವ್ಯ ವಿಭೂತಿಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ವಿವರಿಸಿ.',
17: 'ಹೇ ಯೋಗೇಶ್ವರ, ಸದಾ ನಿಮ್ಮನ್ನು ಧ್ಯಾನಿಸುತ್ತಾ ನಾನು ನಿಮ್ಮನ್ನು ಹೇಗೆ ತಿಳಿಯಲಿ? ಹೇ ಭಗವನ್, ಯಾವ ಯಾವ ರೂಪಗಳಲ್ಲಿ ನಿಮ್ಮನ್ನು ಧ್ಯಾನಿಸಲಿ?',
18: 'ಹೇ ಜನಾರ್ದನ, ನಿಮ್ಮ ಯೋಗಶಕ್ತಿ ಮತ್ತು ವಿಭೂತಿಗಳನ್ನು ಮತ್ತೆ ವಿಸ್ತಾರವಾಗಿ ಹೇಳಿ, ಏಕೆಂದರೆ ನಿಮ್ಮ ಅಮೃತದಂತಹ ಮಾತುಗಳನ್ನು ಕೇಳುತ್ತಾ ನನಗೆ ತೃಪ್ತಿಯಾಗುತ್ತಿಲ್ಲ.',
19: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ಸರಿ, ಹೇ ಕುರುಶ್ರೇಷ್ಠ, ನನ್ನ ದಿವ್ಯ ವಿಭೂತಿಗಳನ್ನು ನಿನಗೆ ಹೇಳುತ್ತೇನೆ, ಆದರೆ ಮುಖ್ಯವಾದವನ್ನು ಮಾತ್ರ, ಏಕೆಂದರೆ ನನ್ನ ವಿಸ್ತಾರಕ್ಕೆ ಕೊನೆಯಿಲ್ಲ.',
21: 'ಆದಿತ್ಯರಲ್ಲಿ ನಾನು ವಿಷ್ಣು, ಜ್ಯೋತಿಗಳಲ್ಲಿ ಕಿರಣಗಳುಳ್ಳ ಸೂರ್ಯ, ಮರುತ್ತರಲ್ಲಿ ಮರೀಚಿ, ನಕ್ಷತ್ರಗಳಲ್ಲಿ ಚಂದ್ರ.',
22: 'ವೇದಗಳಲ್ಲಿ ನಾನು ಸಾಮವೇದ, ದೇವತೆಗಳಲ್ಲಿ ಇಂದ್ರ, ಇಂದ್ರಿಯಗಳಲ್ಲಿ ಮನಸ್ಸು, ಜೀವಿಗಳಲ್ಲಿ ಚೈತನ್ಯ.',
23: 'ರುದ್ರರಲ್ಲಿ ನಾನು ಶಂಕರ, ಯಕ್ಷರಾಕ್ಷಸರಲ್ಲಿ ಧನಪತಿ ಕುಬೇರ, ವಸುಗಳಲ್ಲಿ ಅಗ್ನಿ, ಪರ್ವತಗಳಲ್ಲಿ ಮೇರು.',
24: 'ಹೇ ಪಾರ್ಥ, ಪುರೋಹಿತರಲ್ಲಿ ಮುಖ್ಯನಾದ ಬೃಹಸ್ಪತಿ ಎಂದು ನನ್ನನ್ನು ತಿಳಿ. ಸೇನಾಪತಿಗಳಲ್ಲಿ ನಾನು ಸ್ಕಂದ (ಕುಮಾರಸ್ವಾಮಿ), ಜಲಾಶಯಗಳಲ್ಲಿ ಸಮುದ್ರ.',
25: 'ಮಹರ್ಷಿಗಳಲ್ಲಿ ನಾನು ಭೃಗು, ಮಾತುಗಳಲ್ಲಿ ಏಕಾಕ್ಷರ ಓಂ, ಯಜ್ಞಗಳಲ್ಲಿ ಜಪಯಜ್ಞ, ಸ್ಥಿರವಾದವುಗಳಲ್ಲಿ ಹಿಮಾಲಯ.',
26: 'ಎಲ್ಲ ಮರಗಳಲ್ಲಿ ನಾನು ಅಶ್ವತ್ಥ (ಅರಳಿ), ದೇವರ್ಷಿಗಳಲ್ಲಿ ನಾರದ, ಗಂಧರ್ವರಲ್ಲಿ ಚಿತ್ರರಥ, ಸಿದ್ಧರಲ್ಲಿ ಕಪಿಲ ಮುನಿ.',
27: 'ಕುದುರೆಗಳಲ್ಲಿ ಅಮೃತದೊಂದಿಗೆ ಸಮುದ್ರಮಥನದಲ್ಲಿ ಹುಟ್ಟಿದ ಉಚ್ಚೈಃಶ್ರವಸ್ ಎಂದು ನನ್ನನ್ನು ತಿಳಿ, ದೊಡ್ಡ ಆನೆಗಳಲ್ಲಿ ಐರಾವತ, ಮನುಷ್ಯರಲ್ಲಿ ರಾಜ.',
28: 'ಆಯುಧಗಳಲ್ಲಿ ನಾನು ವಜ್ರಾಯುಧ, ಹಸುಗಳಲ್ಲಿ ಕಾಮಧೇನು, ಸಂತಾನವನ್ನು ಹುಟ್ಟಿಸುವ ಮನ್ಮಥ ನಾನು, ಸರ್ಪಗಳಲ್ಲಿ ವಾಸುಕಿ.',
29: 'ನಾಗಗಳಲ್ಲಿ ನಾನು ಅನಂತ (ಆದಿಶೇಷ), ಜಲಚರಗಳಲ್ಲಿ ವರುಣ, ಪಿತೃಗಳಲ್ಲಿ ಅರ್ಯಮ, ನಿಯಮವನ್ನು ಪಾಲಿಸುವವರಲ್ಲಿ ಯಮ.',
30: 'ದೈತ್ಯರಲ್ಲಿ ನಾನು ಪ್ರಹ್ಲಾದ, ಎಣಿಸುವವುಗಳಲ್ಲಿ ಕಾಲ, ಮೃಗಗಳಲ್ಲಿ ಸಿಂಹ, ಪಕ್ಷಿಗಳಲ್ಲಿ ಗರುಡ.',
31: 'ಪವಿತ್ರಗೊಳಿಸುವವುಗಳಲ್ಲಿ ನಾನು ವಾಯು, ಶಸ್ತ್ರಧಾರಿಗಳಲ್ಲಿ ರಾಮ, ಜಲಜಂತುಗಳಲ್ಲಿ ಮೊಸಳೆ, ನದಿಗಳಲ್ಲಿ ಗಂಗೆ.',
32: 'ಹೇ ಅರ್ಜುನ, ಸೃಷ್ಟಿಗಳ ಆದಿ, ಅಂತ್ಯ ಮತ್ತು ಮಧ್ಯವೂ ನಾನೇ. ವಿದ್ಯೆಗಳಲ್ಲಿ ಆತ್ಮವಿದ್ಯೆ, ವಾದಿಸುವವರಲ್ಲಿ ಸತ್ಯವನ್ನು ಹುಡುಕುವ ತರ್ಕ ನಾನು.',
33: 'ಅಕ್ಷರಗಳಲ್ಲಿ ನಾನು "ಅ", ಸಮಾಸಗಳಲ್ಲಿ ದ್ವಂದ್ವ ಸಮಾಸ. ಅಕ್ಷಯ ಕಾಲವೂ ನಾನೇ, ಎಲ್ಲ ದಿಕ್ಕುಗಳಿಗೂ ಮುಖವಿರುವ, ಎಲ್ಲರನ್ನೂ ಧರಿಸುವವನೂ ನಾನೇ.',
34: 'ಎಲ್ಲವನ್ನೂ ಸೆಳೆದೊಯ್ಯುವ ಮೃತ್ಯು ನಾನು, ಮುಂದೆ ಬರುವ ಎಲ್ಲದರ ಉತ್ಪತ್ತಿ ನಾನು. ಸ್ತ್ರೀಗುಣಗಳಲ್ಲಿ ಕೀರ್ತಿ, ಶ್ರೀ, ವಾಕ್, ಸ್ಮೃತಿ, ಮೇಧಾ, ಧೃತಿ ಮತ್ತು ಕ್ಷಮೆ ನಾನು.',
35: 'ಸಾಮಗಾನಗಳಲ್ಲಿ ನಾನು ಬೃಹತ್ಸಾಮ, ಛಂದಸ್ಸುಗಳಲ್ಲಿ ಗಾಯತ್ರಿ, ತಿಂಗಳುಗಳಲ್ಲಿ ಮಾರ್ಗಶಿರ, ಋತುಗಳಲ್ಲಿ ಹೂ ಅರಳಿಸುವ ವಸಂತ.',
36: 'ಮೋಸ ಮಾಡುವವರಲ್ಲಿ ನಾನು ಜೂಜು, ತೇಜಸ್ವಿಗಳ ತೇಜಸ್ಸು ನಾನು. ನಾನೇ ವಿಜಯ, ನಾನೇ ನಿಶ್ಚಯ, ಸಾತ್ತ್ವಿಕರ ಸತ್ತ್ವ ನಾನು.',
37: 'ವೃಷ್ಣಿಗಳಲ್ಲಿ ನಾನು ವಾಸುದೇವ (ಶ್ರೀಕೃಷ್ಣ), ಪಾಂಡವರಲ್ಲಿ ಧನಂಜಯ (ಅರ್ಜುನ), ಮುನಿಗಳಲ್ಲಿ ವ್ಯಾಸ, ಕವಿಗಳಲ್ಲಿ ಉಶನ (ಶುಕ್ರಾಚಾರ್ಯ).',
38: 'ಶಿಕ್ಷಿಸುವವರ ದಂಡ ನಾನು, ಗೆಲುವು ಬಯಸುವವರ ನೀತಿ ನಾನು, ರಹಸ್ಯಗಳಲ್ಲಿ ಮೌನ, ಜ್ಞಾನಿಗಳ ಜ್ಞಾನ ನಾನು.',
39: 'ಹೇ ಅರ್ಜುನ, ಎಲ್ಲ ಜೀವಿಗಳ ಬೀಜವೂ ನಾನೇ. ಚರವಾಗಲಿ ಅಚರವಾಗಲಿ, ನಾನಿಲ್ಲದೆ ಇರಬಲ್ಲ ಯಾವ ಜೀವಿಯೂ ಇಲ್ಲ.',
40: 'ಹೇ ಪರಂತಪ, ನನ್ನ ದಿವ್ಯ ವಿಭೂತಿಗಳಿಗೆ ಕೊನೆಯಿಲ್ಲ. ನನ್ನ ವಿಭೂತಿಗಳ ವಿಸ್ತಾರಕ್ಕೆ ಇದು ಒಂದು ಸಣ್ಣ ಉದಾಹರಣೆ ಮಾತ್ರ.',
42: 'ಆದರೆ ಹೇ ಅರ್ಜುನ, ಇಷ್ಟು ವಿಸ್ತಾರವಾಗಿ ತಿಳಿಯುವ ಅಗತ್ಯ ನಿನಗೇನು? ಈ ಇಡೀ ಜಗತ್ತನ್ನು ನಾನು ನನ್ನ ಒಂದು ಸಣ್ಣ ಅಂಶದಿಂದ ಧರಿಸಿದ್ದೇನೆ.',
}
